53	<script>
54	const lista = document.getElementById('lista');
55	const mensagem = document.getElementById('mensagem');
56	const campoArgumentos = document.querySelectorAll('.argumentos input[type=checkbox]');
57	const campos = {
58	  id: document.getElementById('campo-id'),
59	  nome: document.getElementById('campo-nome'),
60	  frases: document.getElementById('campo-frases'),
61	  resposta: document.getElementById('campo-resposta'),
62	  tentativas: document.getElementById('campo-tentativas'),
63	};
64	
65	function mostrar(texto, tipo) {
66	  mensagem.textContent = texto;
67	  mensagem.className = tipo;
68	}
69	
70	function limparFormulario() {
71	  campos.id.value = '';
72	  campos.id.disabled = false;
73	  campos.nome.value = '';
74	  campos.frases.value = '';
75	  campos.resposta.value = '';
76	  campoArgumentos.forEach(cb => { cb.checked = false; });
77	  campos.tentativas.value = '';
78	  mensagem.className = '';
79	}
80	
81	function preencherFormulario(ficha) {
82	  // Não mexe em `mensagem` aqui: `salvar()` chama esta função logo depois de mostrar o
83	  // resultado, e limpar a classe agora escondia "Publicado."/"Rascunho salvo." na hora que
84	  // deveria aparecer. Quem troca de ficha na lista limpa a mensagem explicitamente.
85	  campos.id.value = ficha.id;
86	  campos.id.disabled = true;
87	  campos.nome.value = ficha.nome || '';
88	  campos.frases.value = (ficha.frases_do_lead || []).join('\n');
89	  campos.resposta.value = ficha.resposta_orientada || '';
90	  const marcados = new Set(ficha.argumentos_permitidos || []);
91	  campoArgumentos.forEach(cb => { cb.checked = marcados.has(cb.value); });
92	  // tentativas_antes_do_corretor ausente/null fica vazio -- nunca um número fabricado (LEI 2).
93	  campos.tentativas.value = ficha.tentativas_antes_do_corretor ?? '';
94	}
95	
96	async function carregarLista() {
97	  const resposta = await fetch('/api/objecoes');
98	  const fichas = await resposta.json();
99	  lista.innerHTML = '';
100	  for (const ficha of fichas) {
101	    const item = document.createElement('li');
102	    item.textContent = ficha.nome || ficha.id;
103	    const selo = document.createElement('span');
104	    selo.className = 'badge ' + ficha.status;
105	    selo.textContent = ficha.status;
106	    item.appendChild(selo);
107	    item.addEventListener('click', () => {
108	      mensagem.className = '';
109	      preencherFormulario(ficha);
110	    });
111	    lista.appendChild(item);
112	  }
113	}
114	
115	async function salvar(status) {
116	  const dados = {
117	    id: campos.id.value.trim(),
118	    nome: campos.nome.value,
119	    frases_do_lead: campos.frases.value.split('\n').map(l => l.trim()).filter(Boolean),
120	    resposta_orientada: campos.resposta.value,
121	    argumentos_permitidos: Array.from(campoArgumentos).filter(cb => cb.checked).map(cb => cb.value),
122	    tentativas_antes_do_corretor: campos.tentativas.value === '' ? null : Number(campos.tentativas.value),
123	    status: status,
124	  };
125	  if (!dados.id) {
126	    mostrar('Preencha o id da ficha.', 'erro');
127	    return;
128	  }
129	  const resposta = await fetch('/api/objecoes/' + encodeURIComponent(dados.id), {
130	    method: 'PUT',
131	    headers: { 'Content-Type': 'application/json' },
132	    body: JSON.stringify(dados),
133	  });
134	  const corpo = await resposta.json();
135	  if (!resposta.ok) {
136	    mostrar(corpo.erro || 'não foi possível salvar', 'erro');
137	    return;
138	  }
139	  mostrar(status === 'publicado' ? 'Publicado.' : 'Rascunho salvo.', 'sucesso');
140	  preencherFormulario(corpo);
141	  await carregarLista();
142	}
143	
144	async function carregarConfiguracaoComercial() {
145	  const resposta = await fetch('/api/configuracao-comercial');
146	  const corpo = await resposta.json();
147	  document.getElementById('config-encaminhar').checked = Boolean(corpo.encaminhar_lead_fora_do_padrao);
148	}
149	
150	async function salvarConfiguracaoComercial() {
151	  const status = document.getElementById('config-status');
152	  const marcado = document.getElementById('config-encaminhar').checked;
153	  const resposta = await fetch('/api/configuracao-comercial', {
154	    method: 'PUT',
155	    headers: { 'Content-Type': 'application/json' },
156	    body: JSON.stringify({ encaminhar_lead_fora_do_padrao: marcado }),
157	  });
158	  status.textContent = resposta.ok ? 'Salvo.' : 'Não foi possível salvar.';
159	}
160	
161	document.getElementById('btn-nova').addEventListener('click', limparFormulario);
162	document.getElementById('btn-rascunho').addEventListener('click', () => salvar('rascunho'));
163	document.getElementById('btn-publicar').addEventListener('click', () => salvar('publicado'));
164	document.getElementById('config-encaminhar').addEventListener('change', salvarConfiguracaoComercial);
165	
166	carregarLista();
167	carregarConfiguracaoComercial();
168	</script>
