"""Adaptador real da porta `RepositorioDeConhecimento` (issue #43, F13): um arquivo JSON por ficha
em `conhecimento/objecoes/<id>.json`, legível e versionável no git — a decisão registrada em
[REDIGIDO]. `RepositorioDeConhecimentoMemoria` é o dublê determinístico para teste (mesmo molde de
`infra/trilha_jsonl.py`, #7).

`id` vem de fora (rota HTTP) e vira nome de arquivo — `_validar_id` é o dono único da forma segura
(slug), para as duas classes nunca divergirem sobre o que é um id aceitável (LEI 11) e para nenhum
`id` conseguir escapar de `conhecimento/objecoes/` (path traversal)."""

from __future__ import annotations

import json
import re
from pathlib import Path

_ID_VALIDO = re.compile(r"^[a-z0-9][a-z0-9_-]{0,63}$")


def _validar_id(id: str) -> None:
    if not _ID_VALIDO.match(id):
        raise ValueError(f"id de ficha inválido: {id!r}")


class RepositorioDeConhecimentoJSON:
    def __init__(self, diretorio: Path) -> None:
        self._diretorio = Path(diretorio)

    def listar_objecoes(self) -> list[dict]:
        if not self._diretorio.exists():
            return []
        return [
            json.loads(caminho.read_text(encoding="utf-8"))
            for caminho in sorted(self._diretorio.glob("*.json"))
        ]

    def obter_objecao(self, id: str) -> dict | None:
        _validar_id(id)
        caminho = self._diretorio / f"{id}.json"
        if not caminho.exists():
            return None
        return json.loads(caminho.read_text(encoding="utf-8"))

    def salvar_objecao(self, id: str, ficha: dict) -> None:
        _validar_id(id)
        self._diretorio.mkdir(parents=True, exist_ok=True)
        caminho = self._diretorio / f"{id}.json"
        caminho.write_text(
            json.dumps(ficha, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )


class RepositorioDeConhecimentoMemoria:
    """Dublê determinístico — mesma interface, sem tocar disco. Para teste de quem consome a porta."""

    def __init__(self) -> None:
        self._fichas: dict[str, dict] = {}

    def listar_objecoes(self) -> list[dict]:
        return [dict(ficha) for ficha in self._fichas.values()]

    def obter_objecao(self, id: str) -> dict | None:
        # issue #69, achado ao escrever o teste do servidor: este dublê não validava o id em
        # leitura, diferente de `RepositorioDeConhecimentoJSON.obter_objecao` (linha 37) — as duas
        # implementações do mesmo `RepositorioDeConhecimento` divergiam sobre o que é um id
        # aceitável (LEI 11), e o teste com o dublê não pegava o defeito real do servidor.
        _validar_id(id)
        ficha = self._fichas.get(id)
        return dict(ficha) if ficha is not None else None

    def salvar_objecao(self, id: str, ficha: dict) -> None:
        _validar_id(id)
        self._fichas[id] = dict(ficha)

"""`ServicoDeConhecimento` (issue #43, F13): caso de uso para listar/ler/salvar fichas de objeção
de preço. A invariante do marcador mora só em `dominio.ficha_objecao.FichaDeObjecao.publicar` —
este serviço nunca reimplementa a regra, só orquestra domínio + porta (mesma disciplina de
`ServicoDeTrilha`, #7): pedir `status="publicado"` sem passar pela validação não é caminho que
exista aqui.
"""

from __future__ import annotations

from collections.abc import Callable, Iterable
from datetime import datetime, timezone

from dominio.ficha_objecao import FichaDeObjecao

from .portas.repositorio_conhecimento import RepositorioDeConhecimento


def _agora_utc_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


class ServicoDeConhecimento:
    def __init__(
        self,
        repositorio: RepositorioDeConhecimento,
        agora: Callable[[], str] = _agora_utc_iso,
    ) -> None:
        """`agora` (#53): relógio injetável — o domínio não lê `datetime.now`, então esta camada
        (que pode fazer IO) fornece o instante. Padrão de produção é o relógio real; testes passam
        um `Callable` fixo para conferir `atualizado_em` sem depender do horário da máquina."""
        self._repositorio = repositorio
        self._agora = agora

    def listar_objecoes(self) -> list[dict]:
        return self._repositorio.listar_objecoes()

    def obter_objecao(self, id: str) -> dict | None:
        return self._repositorio.obter_objecao(id)

    def salvar_objecao(self, dados: dict, ids_dos_planos: Iterable[str] = ()) -> dict:
        """`dados["status"] == "publicado"` passa pela invariante do marcador antes de persistir;
        qualquer outro status (rascunho) persiste como veio, sem validar o texto — publicar recusa
        calado, salvar rascunho não. `ids_dos_planos` (achado B2 da auditoria do PR #45): quem
        chama (a borda HTTP) lê a `/planos` e passa os ids aqui — este serviço só repassa para o
        domínio montar o vocabulário de marcadores por plano, nunca fala com rede."""
        ficha = FichaDeObjecao.de_dict(dados)
        if dados.get("status") == "publicado":
            ficha = ficha.publicar(self._agora(), ids_dos_planos)
        persistido = ficha.para_dict()
        self._repositorio.salvar_objecao(ficha.id, persistido)
        return persistido
